--
-- Table structure for table `carbon_quota`
--

DROP TABLE IF EXISTS `carbon_quota`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `carbon_quota` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `ent_id` bigint NOT NULL COMMENT '企业ID',
  `year` int NOT NULL COMMENT '配额年度',
  `total_allocated` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '累计免费分配配额(tCO2e)',
  `available` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '当前可用余额(tCO2e)',
  `frozen` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '挂单冻结量(tCO2e)',
  `used` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '已用于履约的配额(tCO2e)',
  `bought` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '累计买入(tCO2e)',
  `sold` decimal(14,2) NOT NULL DEFAULT '0.00' COMMENT '累计卖出(tCO2e)',
  `updated_at` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_quota_ent_year` (`ent_id`,`year`),
  KEY `idx_quota_year` (`year`)
) ENGINE=InnoDB AUTO_INCREMENT=122 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='企业碳配额账户表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `carbon_quota`
